const src = $input.first().json;
let url = String(src.url || src['Adresse de la page'] || '').trim();
const marque = String(src.marque || src['Nom de la marque'] || '').trim();
if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url;
let origine = '';
try { origine = new URL(url).origin; } catch (e) { origine = ''; }
return [{ json: { url: url, marque: marque, origine: origine, llms_url: origine ? origine + '/llms.txt' : '' } }];

const cfg = $('Préparer la demande').first().json;
const pageItem = $('Récupérer la page').first().json;
const llmsItem = $('Chercher llms.txt').first().json;
const html = String(pageItem.data || pageItem.body || '');
const llmsTexte = String(llmsItem.data || llmsItem.body || '');
const llmsTrouve = llmsTexte.length > 20 && !/<html/i.test(llmsTexte);

if (!html || html.length < 200) {
  return [{ json: Object.assign({}, cfg, { erreur: 'page inaccessible ou vide', score: 0, score_seo: 0, score_ia: 0, score_geo: 0, constats: 'La page n a pas pu etre lue.', llms_txt: llmsTrouve, titre: '', meta_description: '', h1: '', mots: 0, donnees_structurees: '', h2: 0, h3: 0, listes: 0, tableaux: 0, chiffres: 0, mentions_marque: 0, images: 0, images_sans_alt: 0, liens_internes: 0, liens_externes: 0, og: false }) }];
}

const nettoye = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ');
const texte = nettoye.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const mots = texte ? texte.split(' ').length : 0;

function premier(re) { const m = html.match(re); return m ? m[1].replace(/\s+/g, ' ').trim() : ''; }
const titre = premier(/<title[^>]*>([\s\S]*?)<\/title>/i);
const langue = premier(/<html[^>]*\slang=["']([^"']+)["']/i);
const canonical = /<link[^>]+rel=["']canonical["']/i.test(html);

let metaDescription = '';
const metas = html.match(/<meta[^>]+>/gi) || [];
let ogTitre = false, ogDescription = false, robotsNoindex = false;
for (const m of metas) {
  const nom = (m.match(/\s(?:name|property)=["']([^"']+)["']/i) || [null, ''])[1].toLowerCase();
  const contenu = (m.match(/\scontent=["']([^"']*)["']/i) || [null, ''])[1];
  if (nom === 'description') metaDescription = contenu.replace(/\s+/g, ' ').trim();
  if (nom === 'og:title') ogTitre = true;
  if (nom === 'og:description') ogDescription = true;
  if (nom === 'robots' && /noindex/i.test(contenu)) robotsNoindex = true;
}

const h1s = (html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/gi) || []).map(h => h.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
const h2s = (html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || []).map(h => h.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
const h3s = (html.match(/<h3[^>]*>([\s\S]*?)<\/h3>/gi) || []).length;
const titresQuestions = h2s.concat(h1s).filter(t => t.includes('?')).length;

const images = (html.match(/<img[^>]*>/gi) || []);
const imagesSansAlt = images.filter(i => !/\salt=["'][^"']+["']/i.test(i)).length;

let hote = '';
try { hote = new URL(cfg.url).host; } catch (e) { hote = ''; }
const liens = (html.match(/<a[^>]+href=["']([^"']+)["']/gi) || []).map(a => (a.match(/href=["']([^"']+)["']/i) || [null, ''])[1]);
const liensInternes = liens.filter(h => h.startsWith('/') || (hote && h.includes(hote))).length;
const liensExternes = liens.filter(h => /^https?:\/\//i.test(h) && hote && !h.includes(hote)).length;

const blocsJsonLd = (html.match(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi) || []);
const types = new Set();
let auteur = false, datePubliee = false, dateModifiee = false;
for (const bloc of blocsJsonLd) {
  const brut = bloc.replace(/^[\s\S]*?>/, '').replace(/<\/script>$/i, '');
  try {
    const data = JSON.parse(brut);
    const liste = Array.isArray(data) ? data : (data['@graph'] && Array.isArray(data['@graph']) ? data['@graph'] : [data]);
    for (const o of liste) {
      if (!o || typeof o !== 'object') continue;
      const t = o['@type'];
      if (Array.isArray(t)) t.forEach(x => types.add(String(x)));
      else if (t) types.add(String(t));
      if (o.author) auteur = true;
      if (o.datePublished) datePubliee = true;
      if (o.dateModified) dateModifiee = true;
    }
  } catch (e) { /* bloc illisible, ignore */ }
}
const typesListe = Array.from(types).sort();
const faq = typesListe.some(t => /FAQPage|Question|HowTo/i.test(t));
if (!auteur) auteur = /rel=["']author["']/i.test(html) || /itemprop=["']author["']/i.test(html);
if (!dateModifiee) dateModifiee = /<time[^>]+datetime=/i.test(html);

const listes = (nettoye.match(/<(ul|ol)[^>]*>/gi) || []).length;
const tableaux = (nettoye.match(/<table[^>]*>/gi) || []).length;
const chiffres = (texte.match(/\d+\s?(%|€|\$|ans|jours|heures|minutes|clients|utilisateurs|fois)/gi) || []).length;
const marque = String(cfg.marque || '').trim();
const mentionsMarque = marque ? (texte.toLowerCase().split(marque.toLowerCase()).length - 1) : 0;

let scoreSeo = 0;
const constats = [];
if (titre) { scoreSeo += 4; if (titre.length >= 30 && titre.length <= 65) scoreSeo += 4; else constats.push('Titre de ' + titre.length + ' caracteres, viser 30 a 65.'); } else constats.push('Aucune balise titre.');
if (metaDescription) { scoreSeo += 4; if (metaDescription.length >= 70 && metaDescription.length <= 160) scoreSeo += 4; else constats.push('Meta description de ' + metaDescription.length + ' caracteres, viser 70 a 160.'); } else constats.push('Aucune meta description.');
if (h1s.length === 1) scoreSeo += 6; else constats.push(h1s.length + ' balises h1 trouvees, il en faut exactement une.');
if (canonical) scoreSeo += 4; else constats.push('Pas de lien canonique.');
if (langue) scoreSeo += 2; else constats.push('Langue de la page non declaree.');
if (images.length === 0 || imagesSansAlt / images.length <= 0.2) scoreSeo += 6; else constats.push(imagesSansAlt + ' images sur ' + images.length + ' sans texte alternatif.');
if (liensInternes >= 3) scoreSeo += 6; else constats.push('Seulement ' + liensInternes + ' liens internes.');
if (robotsNoindex) { scoreSeo = Math.max(0, scoreSeo - 10); constats.push('La page est en noindex, elle ne sera pas indexee.'); }

let scoreIa = 0;
if (h2s.length >= 3) scoreIa += 8; else constats.push('Seulement ' + h2s.length + ' sous titres h2, la structure est trop plate pour etre citee.');
if (listes + tableaux >= 2) scoreIa += 6; else constats.push('Peu de listes ou de tableaux, les IA reprennent mal le texte en blocs.');
if (titresQuestions >= 1) scoreIa += 4; else constats.push('Aucun titre formule comme une question.');
if (mots >= 300) scoreIa += 6; else constats.push('Contenu de ' + mots + ' mots, trop court pour etre une source.');
if (typesListe.length > 0) scoreIa += 6; else constats.push('Aucune donnee structuree JSON-LD.');

let scoreGeo = 0;
if (faq) scoreGeo += 6; else constats.push('Pas de schema FAQ, Question ou HowTo.');
if (auteur) scoreGeo += 5; else constats.push('Aucun auteur identifiable.');
if (dateModifiee || datePubliee) scoreGeo += 5; else constats.push('Aucune date de publication ou de mise a jour.');
if (chiffres >= 5) scoreGeo += 6; else constats.push('Seulement ' + chiffres + ' preuves chiffrees reperees.');
if (!marque) scoreGeo += 2;
else if (mentionsMarque >= 3) scoreGeo += 4;
else constats.push('La marque ' + marque + ' n apparait que ' + mentionsMarque + ' fois dans le texte.');
if (llmsTrouve) scoreGeo += 4; else constats.push('Pas de fichier llms.txt a la racine du site.');

const score = Math.min(100, scoreSeo + scoreIa + scoreGeo);

return [{ json: Object.assign({}, cfg, {
  erreur: '',
  score: score,
  score_seo: scoreSeo,
  score_ia: scoreIa,
  score_geo: scoreGeo,
  titre: titre,
  meta_description: metaDescription,
  h1: h1s[0] || '',
  mots: mots,
  donnees_structurees: typesListe.join(', '),
  llms_txt: llmsTrouve,
  liens_internes: liensInternes,
  liens_externes: liensExternes,
  h2: h2s.length,
  h3: h3s,
  listes: listes,
  tableaux: tableaux,
  chiffres: chiffres,
  mentions_marque: mentionsMarque,
  images: images.length,
  images_sans_alt: imagesSansAlt,
  og: ogTitre && ogDescription,
  constats: constats.join(' ')
}) }];

const audit = $('Analyser la page').first().json;
const reponse = $input.first().json;
let texte = '';
if (Array.isArray(reponse.content)) {
  texte = reponse.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n').trim();
} else if (typeof reponse.text === 'string') {
  texte = reponse.text.trim();
}
if (!texte) texte = 'Recommandations indisponibles, relancez l audit.';

// Pas de tiret long ni de markdown dans un texte visible.
texte = texte
  .replace(/\s*[\u2014\u2013]\s*/g, ' : ')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/\*\*/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: Object.assign({}, audit, { recommandations: texte, audit_at: new Date().toISOString() }) }];
